// Central config - change Instagram credentials here only
// Replace these two values before activating the workflow

const config = {
  instagramAccountId: 'YOUR_INSTAGRAM_BUSINESS_ACCOUNT_ID',
  accessToken:        'YOUR_INSTAGRAM_ACCESS_TOKEN',
  postsToFetch:       5,
  commentsPerPost:    30,
  todayDate:          new Date().toISOString().split('T')[0]
};

return [{ json: config }];

// Extract posts array and attach config fields for downstream use
const config  = $('2. Code - Set Config and Credentials').first().json;
const apiResp = $json;

const posts = apiResp.data || [];

if (posts.length === 0) {
  throw new Error('No Instagram posts found. Check your account ID and access token.');
}

return posts.map(function(post) {
  return {
    json: {
      postId:      post.id,
      caption:     (post.caption || '').substring(0, 200),
      permalink:   post.permalink || '',
      timestamp:   post.timestamp || '',
      mediaType:   post.media_type || '',
      accessToken: config.accessToken,
      commentsPerPost: config.commentsPerPost,
      todayDate:   config.todayDate
    }
  };
});

// Extract comments array for this post
// Attach post context to each comment for later use
const postCtx   = $('5. Loop - Process Each Post').first().json;
const apiResp   = $json;
const comments  = apiResp.data || [];

if (comments.length === 0) {
  // No comments on this post - return a marker item with empty text
  // so the comment loop still runs and hands control back to the post loop
  return [{
    json: {
      commentId:   'none_' + postCtx.postId,
      commentText: '',
      username:    'none',
      commentAt:   '',
      postId:      postCtx.postId,
      postUrl:     postCtx.permalink,
      accessToken: postCtx.accessToken,
      todayDate:   postCtx.todayDate
    }
  }];
}

return comments.map(function(c) {
  return {
    json: {
      commentId:   c.id,
      commentText: (c.text || '').trim(),
      username:    c.username || 'unknown',
      commentAt:   c.timestamp || '',
      postId:      postCtx.postId,
      postUrl:     postCtx.permalink,
      accessToken: postCtx.accessToken,
      todayDate:   postCtx.todayDate
    }
  };
});

