// Parse the AI sentiment result and merge with comment context
const aiResp     = $json;
const commentCtx = $('8. Loop - Process Each Comment').first().json;

const raw = aiResp?.choices?.[0]?.message?.content || '';

let sentiment = 'NEUTRAL';
let score     = 0.5;
let reason    = '';

try {
  const cleaned = raw.trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
  const parsed  = JSON.parse(cleaned);
  sentiment     = (parsed.sentiment || 'NEUTRAL').toUpperCase();
  score         = parseFloat(parsed.score) || 0.5;
  reason        = parsed.reason || '';
} catch(e) {
  // If parse fails, default to NEUTRAL so we skip it
  sentiment = 'NEUTRAL';
}

// Validate sentiment label
if (!['POSITIVE','NEUTRAL','NEGATIVE'].includes(sentiment)) {
  sentiment = 'NEUTRAL';
}

return [{
  json: {
    commentId:    commentCtx.commentId,
    commentText:  commentCtx.commentText,
    username:     commentCtx.username,
    commentAt:    commentCtx.commentAt,
    postId:       commentCtx.postId,
    postUrl:      commentCtx.postUrl,
    todayDate:    commentCtx.todayDate,
    sentiment,
    score,
    reason
  }
}];

// Check if this comment ID already exists in the sheet
// The Sheets lookup returns matching rows. With Always Output Data on,
// an empty result still comes through as one item with an empty json object.
const items      = $input.all();
const commentCtx = $('10. Code - Parse Sentiment Label').first().json;

const isDuplicate = items.some(function(item) {
  return item.json && item.json['Comment ID'];
});

return [{
  json: {
    ...commentCtx,
    isDuplicate
  }
}];

// Build the daily digest HTML email from today's saved comments
const allRows = $input.all();
const today   = new Date().toISOString().split('T')[0];

// Keep only real rows saved today
// With Always Output Data on, an empty sheet still passes one empty item through
const rows = allRows.filter(function(item) {
  const d = item.json || {};
  return d['Comment ID'] && String(d.Date || '') === today;
});

if (rows.length === 0) {
  return [{
    json: {
      emailSubject: 'Instagram Positive Comments Digest - ' + today + ' - No positive comments today',
      htmlEmail: '<p>No positive comments were found today. Keep posting great content!</p>',
      commentCount: 0,
      todayDate: today
    }
  }];
}

// Build comment cards
const commentCards = rows.map(function(item) {
  const d = item.json;
  const scoreVal = parseFloat(d['Sentiment Score'] || 0.5);

  return '<div style="background:#f0fdf4;border-left:4px solid #22c55e;border-radius:0 8px 8px 0;padding:14px 16px;margin-bottom:12px;">'
    + '<div style="display:flex;justify-content:space-between;margin-bottom:6px;">'
    + '<span style="font-size:13px;font-weight:700;color:#166534;">@' + (d.Username || 'unknown') + '</span>'
    + '<span style="font-size:11px;color:#888;">' + (d.Date || today) + '</span>'
    + '</div>'
    + '<p style="margin:0;font-size:14px;color:#333;line-height:1.6;">"' + (d['Comment Text'] || '') + '"</p>'
    + '<div style="margin-top:8px;font-size:11px;color:#666;">'
    + 'Score: ' + scoreVal.toFixed(2) + ' | Post: <a href="' + (d['Post URL'] || '#') + '" style="color:#22c55e;">View Post</a>'
    + '</div>'
    + '</div>';
}).join('');

const htmlEmail =
  '<div style="font-family:Arial,sans-serif;max-width:680px;margin:0 auto;background:#f5f5f5;">'
  + '<div style="background:linear-gradient(135deg,#7c3aed 0%,#db2777 100%);padding:26px 28px;border-radius:8px 8px 0 0;">'
  + '<h1 style="color:#fff;font-size:19px;margin:0;">Instagram Positive Comments - ' + today + '</h1>'
  + '<p style="color:#f3e8ff;font-size:13px;margin:6px 0 0;">' + rows.length + ' positive comment(s) found today</p>'
  + '</div>'
  + '<div style="background:#fff;padding:22px 24px;">'
  + '<p style="font-size:14px;color:#333;line-height:1.7;margin:0 0 18px;">Here are today\'s positive Instagram comments. These are real customer voices showing appreciation for your content and brand.</p>'
  + commentCards
  + '<div style="background:#f3f4f6;border-radius:6px;padding:12px 16px;margin-top:16px;">'
  + '<p style="font-size:11px;color:#888;margin:0;">Sentiment analysis by OpenAI. Only comments classified POSITIVE are saved. View full data in Google Sheets.</p>'
  + '</div>'
  + '</div>'
  + '<div style="background:#7c3aed;padding:12px 24px;text-align:center;border-radius:0 0 8px 8px;">'
  + '<p style="color:#f3e8ff;font-size:11px;margin:0;">Instagram Sentiment Tracker - n8n + OpenAI</p>'
  + '</div>'
  + '</div>';

return [{
  json: {
    emailSubject: 'Instagram Digest - ' + rows.length + ' Positive Comments - ' + today,
    htmlEmail,
    commentCount: rows.length,
    todayDate: today
  }
}];
